const people=['مریم احمدی','رضا کریمی','علی رضایی','سارا محمدی'];const $=s=>document.querySelector(s),key='kargah-demo-v1';const now=()=>new Date().toISOString();const day=n=>{let d=new Date();d.setDate(d.getDate()+n);return d.toISOString().slice(0,10)};const fmt=s=>s?new Intl.DateTimeFormat('fa-IR',{timeZone:'Asia/Tehran',dateStyle:'medium'}).format(new Date(s)):'تعیین نشده';const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));let tasks;try{tasks=JSON.parse(localStorage.getItem(key))}catch{}if(!Array.isArray(tasks))tasks=[{title:'اجرای لوله‌کشی طبقه دوم',description:'تکمیل مسیر آب سرد و گرم و بررسی اتصالات قبل از تست.',owner:3,status:'در حال انجام',priority:'مهم',due:day(2)},{title:'آماده‌سازی محل بتن‌ریزی',description:'پاک‌سازی محدوده و کنترل قالب‌بندی محور شرقی.',owner:2,status:'تعریف‌شده',priority:'فوری',due:day(-1)},{title:'پیگیری تأمین سیمان',description:'هماهنگی زمان ارسال با تأمین‌کننده؛ منتظر موجودی انبار.',owner:1,status:'متوقف‌شده',reason:'منتظر اعلام موجودی تأمین‌کننده',priority:'مهم',due:day(1)},{title:'بازدید ایمنی داربست‌ها',description:'بررسی اتصالات و مسیر دسترسی طبقه اول؛ فعالیت ثبت‌شده توسط نیرو.',owner:2,creator:2,status:'در حال انجام',priority:'عادی',due:day(3)},{title:'تحویل ابزارهای کارگاه',description:'فهرست ابزارها کنترل و به انبار تحویل شد.',owner:1,status:'انجام‌شده',priority:'عادی',due:day(-2),completed:now()}].map((t,i)=>({id:crypto.randomUUID(),created:day(-3),creator:0,reports:[],...t}));let view='active',selected=null;const me=()=>Number($('#person').value),manager=()=>me()<2,late=t=>t.status!=='انجام‌شده'&&t.due&&t.due<day(0);function save(){localStorage.setItem(key,JSON.stringify(tasks));render()}function toast(s){$('#toast').textContent=s;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',2500)}function badge(t){return `<span class="tag ${t.status==='انجام‌شده'?'done':t.status==='در حال انجام'?'progress':t.status==='متوقف‌شده'?'stop':''}">${esc(t.status)}</span>${late(t)?'<span class="tag late">عقب‌افتاده</span>':''}<span class="tag">${esc(t.priority)}</span>`}function render(){let active=tasks.filter(t=>t.status!=='انجام‌شده');$('#activeCount').textContent=active.length;$('#stats').innerHTML=[['کارهای فعال',active.length,'در مسیر انجام'],['در حال انجام',tasks.filter(t=>t.status==='در حال انجام').length,'فعالیت در جریان'],['عقب‌افتاده',tasks.filter(late).length,'نیازمند پیگیری'],['انجام‌شده',tasks.filter(t=>t.status==='انجام‌شده').length,'بدون نیاز به تأیید']].map((x,i)=>`<div class="stat ${i===2?'warn':''}"><span>${x[0]}</span><b>${x[1].toLocaleString('fa-IR')}</b><small>${x[2]}</small></div>`).join('');let names={active:'کارهای فعال',mine:'کارهای من',done:'کارهای انجام‌شده',feed:'فعالیت اعضا'};$('#title').textContent=$('#crumb').textContent=names[view];document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('selected',b.dataset.view===view));$('.toolbar').style.display=view==='feed'?'none':'flex';if(view==='feed'){let logs=tasks.flatMap(t=>[{text:'کار «'+t.title+'» را ثبت کرد.',person:t.creator,time:t.created,id:t.id},...(t.reports||[]).map(r=>({...r,id:t.id}))]).sort((a,b)=>new Date(b.time)-new Date(a.time));$('#list').innerHTML=logs.map(r=>`<div class="task" data-id="${r.id}"><div><strong>${esc(people[r.person])}</strong><p>${esc(r.text)}</p><small>${fmt(r.time)}</small></div></div>`).join('');return}let q=$('#search').value.trim(),sf=$('#statusFilter').value,of=$('#ownerFilter').value;let filtered=tasks.filter(t=>(view==='done'?t.status==='انجام‌شده':view==='mine'?t.owner===me()&&t.status!=='انجام‌شده':t.status!=='انجام‌شده')&&(!q||(t.title+' '+t.description).includes(q))&&(!sf||(sf==='late'?late(t):t.status===sf))&&(of===''||t.owner===Number(of)));$('#list').innerHTML=filtered.length?filtered.map(t=>`<article class="task ${t.status==='انجام‌شده'?'is-done':''}"><button class="task-check ${t.status==='انجام‌شده'?'checked':''}" data-complete="${t.id}" aria-label="${t.status==='انجام‌شده'?'بازگشایی کار':'انجام شد'}" title="${manager()||t.owner===me()?'تغییر وضعیت انجام':'فقط مسئول کار می‌تواند آن را انجام‌شده کند'}" ${manager()||t.owner===me()?'':'disabled'}>${t.status==='انجام‌شده'?'✓':''}</button><div class="task-copy" data-id="${t.id}" tabindex="0" role="button"><h3>${esc(t.title)}</h3><p>${esc(t.description)}</p><div class="meta"><span>تعریف: ${fmt(t.created)}</span><span>مهلت: ${fmt(t.due)}</span>${t.completed?`<span>اتمام: ${fmt(t.completed)}</span>`:''}<span>ثبت‌کننده: ${esc(people[t.creator])}</span></div></div><div class="row-status">${badge(t)}</div><div class="owner"><span class="avatar">${esc(people[t.owner][0])}</span>${esc(people[t.owner])}</div></article>`).join(''):'<div class="empty">کاری برای نمایش وجود ندارد.</div>'}
function detail(id){selected=id;let t=tasks.find(t=>t.id===id);let can=manager()||t.owner===me();$('#detailBody').innerHTML=`<div class="dialog-head"><h2>${esc(t.title)}</h2><button class="close" onclick="document.querySelector('#details').close()">×</button></div><div class="tags">${badge(t)}</div><p>${esc(t.description)}</p><div class="detail-meta">مسئول: ${esc(people[t.owner])}<br>ثبت‌کننده: ${esc(people[t.creator])}<br>تاریخ تعریف: ${fmt(t.created)}<br>مهلت انجام: ${fmt(t.due)}${t.completed?'<br>اتمام: '+fmt(t.completed):''}${t.reason?'<br>دلیل توقف: '+esc(t.reason):''}</div>${can?`<div class="actions">${['در حال انجام','متوقف‌شده','انجام‌شده','تعریف‌شده'].filter(s=>s!==t.status).map(s=>`<button data-status="${s}">${s==='در حال انجام'?'شروع / ادامه کار':s==='تعریف‌شده'?'بازگشایی کار':s}</button>`).join('')}</div>`:''}<h3>گزارش‌ها و پیشرفت</h3><div>${(t.reports||[]).map(r=>`<div class="report"><b>${esc(people[r.person])}</b><br>${esc(r.text)}<br><small>${fmt(r.time)}</small></div>`).join('')||'<p>هنوز گزارشی ثبت نشده.</p>'}</div><form id="reportForm"><label>ثبت گزارش فعالیت<textarea name="report" required rows="2" placeholder="روی چه بخشی کار می‌کنید؟"></textarea></label><button class="primary">ثبت گزارش برای همه</button></form>`;if(!$('#details').open)$('#details').showModal();$('#reportForm').onsubmit=e=>{e.preventDefault();t.reports.push({person:me(),time:now(),text:new FormData(e.target).get('report')});save();detail(id);toast('گزارش ثبت شد')};$('#detailBody').querySelectorAll('[data-status]').forEach(b=>b.onclick=()=>{let reason='';if(b.dataset.status==='متوقف‌شده'){reason=prompt('دلیل توقف کار چیست؟');if(!reason?.trim())return}t.status=b.dataset.status;t.reason=reason;t.completed=t.status==='انجام‌شده'?now():null;t.reports.push({person:me(),time:now(),text:'وضعیت به «'+t.status+'» تغییر کرد.'+(reason?' دلیل: '+reason:'')});save();detail(id);toast(t.status==='انجام‌شده'?'به کارهای انجام‌شده منتقل شد':'وضعیت به‌روز شد')})}
$('#ownerFilter').innerHTML+=people.map((p,i)=>`<option value="${i}">${p}</option>`).join('');$('#taskOwner').innerHTML=people.map((p,i)=>`<option value="${i}">${p}</option>`).join('');document.querySelectorAll('nav button').forEach(b=>b.onclick=()=>{view=b.dataset.view;$('#statusFilter').value='';render()});['#search','#statusFilter','#ownerFilter','#person'].forEach(s=>$(s).addEventListener(s==='#search'?'input':'change',render));$('#list').onclick=e=>{let c=e.target.closest('[data-complete]');if(c){let t=tasks.find(t=>t.id===c.dataset.complete);if(!t||!(manager()||t.owner===me()))return;let done=t.status!=='انجام‌شده';t.status=done?'انجام‌شده':'تعریف‌شده';t.completed=done?now():null;t.reason='';t.reports.push({person:me(),time:now(),text:done?'کار را انجام‌شده کرد.':'کار را دوباره باز کرد.'});save();toast(done?'به انجام‌شده‌ها منتقل شد':'کار دوباره باز شد');return}let t=e.target.closest('[data-id]');if(t)detail(t.dataset.id)};$('#list').onkeydown=e=>{if(e.key==='Enter'){let t=e.target.closest('[data-id]');if(t)detail(t.dataset.id)}};$('#add').onclick=()=>{$('#form').reset();$('#taskOwner').value=me();$('#taskOwner').disabled=!manager();$('#editor').showModal()};$('#editor .close').onclick=()=>$('#editor').close();$('#form').onsubmit=e=>{e.preventDefault();let d=Object.fromEntries(new FormData(e.target));if(!d.title.trim())return;if(d.status==='متوقف‌شده'&&!d.reason.trim()){toast('دلیل توقف را بنویسید');return}let t={...d,title:d.title.trim(),id:crypto.randomUUID(),creator:me(),owner:manager()?Number(d.owner):me(),created:now(),completed:d.status==='انجام‌شده'?now():null,reports:[]};tasks.unshift(t);save();$('#editor').close();view=t.status==='انجام‌شده'?'done':'active';$('#search').value='';$('#ownerFilter').value='';$('#statusFilter').value='';render();toast('کار جدید ثبت شد')};render();
